<script setup>
import {Head,Link,router,usePage,useForm} from '@inertiajs/vue3';import {ref} from 'vue';import AppLayout from '../../Layouts/AppLayout.vue';import Errors from '../../Components/Errors.vue';import ManagementPager from '../../Components/ManagementPager.vue';import {useI18n} from '../../lib/i18n.js';
const {t}=useI18n();
const props=defineProps({collection:Object,words:Object}),form=useForm({title:props.collection.title,description:props.collection.description??''}),sharing=useForm({});
function save(){if(confirm(t('Save these collection details as an administrator?')))form.patch(`/admin/collections/${props.collection.id}`,{preserveScroll:true});}
function disable(){if(confirm(t('Disable sharing as an administrator? The sharing link will stop working and joined accounts will lose access.')))sharing.delete(`/admin/collections/${props.collection.id}/sharing`,{preserveScroll:true});}
</script><template><Head :title="collection.title"/><AppLayout :title="t('Inspect collection')" :subtitle="collection.title"><template #actions><Link href="/admin/collections" class="button secondary">{{t('Collection administration')}}</Link></template><p class="notice">{{t('Administrator view: vocabulary is read-only here. Personal notes are not available.')}}</p><form class="panel" @submit.prevent="save"><Errors :errors="form.errors"/><label>{{t('Title')}}<input v-model="form.title" maxlength="150" required/></label><label>{{t('Description')}}<textarea v-model="form.description" maxlength="2000" rows="3"/></label><button class="button" :disabled="form.processing||sharing.processing">{{t('Save changes')}}</button></form><section class="panel admin-section"><Errors :errors="sharing.errors"/><h2>{{t('Link sharing')}}</h2><button v-if="collection.share_uuid" class="button secondary" :disabled="sharing.processing||form.processing" @click="disable">{{t('Disable sharing')}}</button><p v-else>{{t('Link sharing off')}}</p></section><section class="panel admin-section"><h2>{{t('Words and definitions')}}</h2><article v-for="word in words.data" :key="word.id" class="admin-word"><strong>{{word.term}}</strong><p>{{word.definition}}</p></article><p v-if="!words.data.length">{{t('This collection is waiting for words.')}}</p><ManagementPager :page="words"/></section></AppLayout></template><style scoped>.admin-section{margin-top:20px}.admin-word{padding:14px 0;border-bottom:1px solid #ddd;overflow-wrap:anywhere}.admin-word p{white-space:pre-wrap}</style>